import {CANAL,DISTRICT_PALETTES} from './fantasy-town.js?v=73a';
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function atlasProject(bounds,x,z){return [50+700*(x-bounds.left)/(bounds.right-bounds.left),52+680*(z-bounds.top)/(bounds.bottom-bounds.top)];}
export function atlasSVG(places,bounds,here,selection=null,route=[]){const project=(x,z)=>atlasProject(bounds,x,z),point=(x,z)=>project(x,z).join(','),lanes=[...new Set(places.map(p=>p.lane))];const parks=[[-59,70,22,12,true],[67,-33,19,14,true],[-61,-87,22,14,false],[69,-87,19,12,false]].map(([x,z,rx,rz,pond])=>{const [px,py]=project(x,z),w=rx*700/(bounds.right-bounds.left),h=rz*680/(bounds.bottom-bounds.top);return `<ellipse cx="${px}" cy="${py}" rx="${w}" ry="${h}" fill="#91b69a" stroke="#efe4bd" stroke-width="3"/>${pond?`<ellipse cx="${px}" cy="${py}" rx="${w*.5}" ry="${h*.5}" fill="#79bdc7"/>`:''}`;}).join('');const riverX=project(CANAL.x,0)[0],riverW=700*10/(bounds.right-bounds.left);
 return `<svg viewBox="0 0 800 790" class="atlas-map" role="group" aria-label="Interactive world map"><defs><linearGradient id="atlasSea" x2=".5" y2="1"><stop stop-color="#233e60"/><stop offset="1" stop-color="#3d8b9b"/></linearGradient><linearGradient id="atlasLand" x2=".2" y2="1"><stop stop-color="#bacbb8"/><stop offset="1" stop-color="#e8dfbd"/></linearGradient></defs><rect width="800" height="790" rx="24" fill="url(#atlasSea)"/><path d="M80 35Q400 0 730 35Q790 270 756 690Q650 780 90 745Q10 510 40 130Z" fill="#152f4c" opacity=".28" transform="translate(5 10)"/><path d="M80 35Q400 0 730 35Q790 270 756 690Q650 780 90 745Q10 510 40 130Z" fill="url(#atlasLand)"/>${parks}<rect x="${riverX-riverW/2}" y="50" width="${riverW}" height="680" rx="10" fill="#5db5c5"/>${Object.entries(DISTRICT_PALETTES).map(([name],i)=>{const ps=places.filter(p=>p.district===name);if(!ps.length)return '';const z=ps.reduce((a,p)=>a+p.z,0)/ps.length;return `<text x="440" y="${project(0,z)[1]-30}" class="atlas-district">${esc(name)}</text>`;}).join('')}${[-110,10,110].map(x=>`<path d="M${point(x,Math.min(...lanes))}L${point(x,Math.max(...lanes))}" class="atlas-road"/>`).join('')}${lanes.map(z=>`<path d="M${point(-110,z)}L${point(110,z)}" class="atlas-road"/>`).join('')}${route.length?`<polyline points="${route.map(p=>point(...p)).join(' ')}" fill="none" stroke="#bb6b3d" stroke-width="5" stroke-linecap="round" stroke-dasharray="4 9"/>`:''}${places.map(p=>{const [x,y]=project(p.x,p.z);return `<g data-atlas-pin="${esc(p.id)}" role="button" tabindex="0" aria-label="${esc(p.name)}" class="atlas-pin ${selection===p.id?'selected':''}" transform="translate(${x} ${y})"><title>${esc(p.name)}</title><circle r="18" fill="${p.swatch}"/><text text-anchor="middle" dominant-baseline="central">${p.icon}</text></g>`;}).join('')}<circle cx="${project(here.x,here.z)[0]}" cy="${project(here.x,here.z)[1]}" r="8" fill="#235d9e" stroke="white" stroke-width="4"/><g transform="translate(723 88)" fill="#fff6d9"><text text-anchor="middle" y="-14" font-size="15">N</text><path d="M0-5 8 18 0 13-8 18Z"/></g><text x="38" y="772" fill="#e8efd9" font-size="12" letter-spacing="2">SESAME STREET • WONDER ISLES</text></svg>`;
}
